module TradeOptimizer(\n    input clk,\n    input rst_n,\n    input start,\n    input [2:0] trade_offer[0:7],\n    input [2:0] trade_want[0:7],\n    input [15:0] trade_rate[0:7],\n    output reg [15:0] result,\n    output reg done\n);\n\n    // State declarations\n    localparam [2:0] IDLE          = 3'd0;\n    localparam [2:0] CHECK_TRADE   = 3'd1;\n    localparam [2:0] CALCULATE     = 3'd2;\n    localparam [2:0] UPDATE_AMOUNT = 3'd3;\n    localparam [2:0] NEXT_TRADE    = 3'd4;\n    localparam [2:0] FINAL_RESULT  = 3'd5;\n    localparam [2:0] FINISH_STATE  = 3'd6;\n\n    reg [2:0] state, next_state;\n    reg [3:0] trade_idx;\n    reg [15:0] amount[0:7];\n    reg [15:0] offer_type, want_type;\n    reg [15:0] rate;\n    reg [15:0] traded_amount;\n    reg [31:0] received_temp;\n    reg [15:0] received;\n    reg [15:0] new_amount;\n    wire [15:0] added_amount;\n    wire overflow;\n\n    // Saturation calculation: added_amount = min(amount[O] + received, 65535)\n    assign added_amount = amount[offer_type] + received;\n    assign overflow = (added_amount < amount[offer_type]) || (added_amount < received);\n\n    // Next state logic\n    always @(*) begin\n        case (state)\n            IDLE: begin\n                if (start) next_state = CHECK_TRADE;\n                else next_state = IDLE;\n            end\n            CHECK_TRADE: begin\n                if (trade_idx >= 8'd8) next_state = FINAL_RESULT;\n                else if (amount[want_type] > 16'd0) next_state = CALCULATE;\n                else next_state = NEXT_TRADE;\n            end\n            CALCULATE: begin\n                next_state = UPDATE_AMOUNT;\n            end\n            UPDATE_AMOUNT: begin\n                next_state = NEXT_TRADE;\n            end\n            NEXT_TRADE: begin\n                next_state = CHECK_TRADE;\n            end\n            FINAL_RESULT: begin\n                next_state = FINISH_STATE;\n            end\n            FINISH_STATE: begin\n                next_state = IDLE;\n            end\n            default: next_state = IDLE;\n        endcase\n    end\n\n    // Sequential logic\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            trade_idx <= 4'd0;\n            offer_type <= 16'd0;\n            want_type <= 16'd0;\n            rate <= 16'd0;\n            traded_amount <= 16'd0;\n            received_temp <= 32'd0;\n            received <= 16'd0;\n            new_amount <= 16'd0;\n            result <= 16'd0;\n            done <= 1'b0;\n            amount[0] <= 16'd256;\n            amount[1] <= 16'd0;\n            amount[2] <= 16'd0;\n            amount[3] <= 16'd0;\n            amount[4] <= 16'd0;\n            amount[5] <= 16'd0;\n            amount[6] <= 16'd0;\n            amount[7] <= 16'd0;\n        end else begin\n            state <= next_state;\n            done <= 1'b0;\n            \n            case (state)\n                IDLE: begin\n                    // Reset done and prepare for start\n                    if (start) begin\n                        trade_idx <= 4'd0;\n                        result <= 16'd0;\n                        amount[0] <= 16'd256;\n                        amount[1] <= 16'd0;\n                        amount[2] <= 16'd0;\n                        amount[3] <= 16'd0;\n                        amount[4] <= 16'd0;\n                        amount[5] <= 16'd0;\n                        amount[6] <= 16'd0;\n                        amount[7] <= 16'd0;\n                    end\n                end\n                \n                CHECK_TRADE: begin\n                    // Load current trade data\n                    if (trade_idx < 4'd8) begin\n                        offer_type <= {13'd0, trade_offer[trade_idx]};\n                        want_type <= {13'd0, trade_want[trade_idx]};\n                        rate <= trade_rate[trade_idx];\n                    end\n                end\n                \n                CALCULATE: begin\n                    // All of want_type goes to exchange\n                    traded_amount <= amount[want_type];\n                    // Clear the source\n                    amount[want_type] <= 16'd0;\n                    // Multiply: Q8.8 * Q8.8 = Q16.16, shift right 8 for Q8.8\n                    // (traded * rate) >> 8\n                    received_temp <= traded_amount * rate;\n                end\n                \n                UPDATE_AMOUNT: begin\n                    // Extract Q8.8 result from 32-bit multiplication\n                    received <= received_temp[23:8];\n                    // Add with saturation\n                    if (overflow) begin\n                        amount[offer_type] <= 16'd65535;\n                    end else begin\n                        amount[offer_type] <= added_amount;\n                    end\n                end\n                \n                NEXT_TRADE: begin\n                    trade_idx <= trade_idx + 4'd1;\n                end\n                \n                FINAL_RESULT: begin\n                    // Get blue lemonade amount (type 1)\n                    // Convert from Q8.8 to integer liters: shift right 8\n                    // Clamp to max 10 liters (10 * 256 = 2560)\n                    if (amount[1][15:8] >= 8'd10) begin\n                        result <= 16'd10;\n                    end else begin\n                        result <= {8'd0, amount[1][15:8]};\n                    end\n                end\n                \n                FINISH_STATE: begin\n                    done <= 1'b1;\n                end\n                \n                default: begin\n                    state <= IDLE;\n                end\n            endcase\n        end\n    end\n\nendmodule